import{_ as o,o as t,c,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/GET-DATA-_002fTYPE_003dGNM_002fODS.md","filePath":"manual-zh/GET-DATA-_002fTYPE_003dGNM_002fODS.md","lastUpdated":1785684581000}'),d={name:"manual-zh/GET-DATA-_002fTYPE_003dGNM_002fODS.md"};function r(n,e,E,_,p,T){return t(),c("div",null,[...e[0]||(e[0]=[a(`<h4 id="_9-4-1-电子表格文件" tabindex="-1">9.4.1 电子表格文件 <a class="header-anchor" href="#_9-4-1-电子表格文件" aria-label="Permalink to &quot;9.4.1 电子表格文件&quot;">​</a></h4><pre><code>GET DATA /TYPE={GNM, ODS}
        /FILE={’file_name’}
        /SHEET={NAME ’sheet_name’, INDEX n}
        /CELLRANGE={RANGE ’range’, FULL}
        /READNAMES={ON, OFF}
        /ASSUMEDSTRWIDTH=n.
</code></pre><p>可以使用 <code>GET DATA</code> 命令读取 Gnumeric 电子表格（<a href="http://gnumeric.org" target="_blank" rel="noreferrer">http://gnumeric.org</a>）以及 OpenDocument 格式的电子表格（<a href="http://libreplanet.org/wiki/Group:OpenDocument/Software" target="_blank" rel="noreferrer">http://libreplanet.org/wiki/Group:OpenDocument/Software</a>）。使用 <code>TYPE</code> 子命令指示文件的格式。/TYPE=GNM 表示 Gnumeric 文件，/TYPE=ODS 表示 OpenDocument。<code>FILE</code> 子命令是必需的。用它指定要读取的文件名。所有其他子命令都是可选的。</p><p>每个变量的格式由包含该变量第一个数据的电子表格单元格的格式决定。如果该单元格为字符串（文本）格式，则变量的宽度由其所含字符串的长度决定，除非给出了 <code>ASSUMEDSTRWIDTH</code> 子命令。</p><p><code>SHEET</code> 子命令指定要读取的电子表格文件中的工作表。<code>SHEET</code> 子命令有两种形式。在第一种形式中，<code>/SHEET=name sheet_name</code>，字符串 sheet_name 是要读取的工作表的名称。在第二种形式中，<code>/SHEET=index idx</code>，idx 是要读取的工作表的索引整数。第一个工作表的索引为 1。如果省略 <code>SHEET</code> 子命令，则命令读取文件中的第一个工作表。</p><p><code>CELLRANGE</code> 子命令指定要读取的工作表中单元格的范围。如果子命令给定为 <code>/CELLRANGE=FULL</code>，则读取整个工作表。要仅读取工作表的一部分，请使用形式 <code>/CELLRANGE=range &#39;top_left_cell:bottom_right_cell&#39;</code>。例如，子命令 <code>/CELLRANGE=range &#39;C3:P19&#39;</code> 读取列 C–P 和行 3–19（含）。如果未给出 <code>CELLRANGE</code> 子命令，则读取整个工作表。</p><p>如果指定 <code>/READNAMES=ON</code>，则第一行单元格的内容用作存储后续行数据的变量名称。这是默认设置。如果使用 <code>/READNAMES=OFF</code>，则变量接收自动分配的名称。</p><p><code>ASSUMEDSTRWIDTH</code> 子命令指定从文件读取的字符串变量的最大宽度。如果省略，默认值由每个变量的第一个电子表格单元格中字符串的长度决定。</p>`,8)])])}const S=o(d,[["render",r]]);export{l as __pageData,S as default};
